414	    /**
415	     * Validates an owner's optional postcode. A {@code null} value means the field was omitted and is
416	     * left unset, keeping the create contract backward-compatible. When a value is present it must be
417	     * exactly 4 digits, and when the owner's region (derived from its city, {@link #regionForCity})
418	     * has a known postcode range in {@link #REGION_POSTCODES} the postcode must fall within that
419	     * inclusive range. A region with no known range ({@code 'UNKNOWN'}) accepts any 4-digit postcode.
420	     * The returned value is stored and returned unchanged.
421	     *
422	     * @param postcode the raw postcode value submitted by the client, or {@code null} if omitted
423	     * @param region   the owner's region derived from its city
424	     * @return the postcode to store, or {@code null} if none was supplied
425	     * @throws InvalidOwnerFieldsException if a value is present but not a valid 4-digit postcode, or is
426	     *                                     out of range for the city's region, yielding a 400 response
427	     */
428	    private String validatePostcode(String postcode, String region) {
429	        if (postcode == null) {
430	            return null;
431	        }
432	        if (!postcode.matches("[0-9]{4}")) {
433	            throw new InvalidOwnerFieldsException(List.of("postcode"));
434	        }
435	        int[] range = REGION_POSTCODES.get(region);
436	        if (range != null) {
437	            int value = Integer.parseInt(postcode);
438	            if (value < range[0] || value > range[1]) {
439	                throw new InvalidOwnerFieldsException(List.of("postcode"));
440	            }
441	        }
442	        return postcode;
443	    }
