465	    /**
466	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
467	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
468	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
469	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits,
470	     * and when the supplied country code is one with a known national-number length
471	     * ({@link #NATIONAL_NUMBER_LENGTHS}, e.g. {@code '+61'} => 9, {@code '+1'} => 10) the national
472	     * number must have exactly that many digits.
473	     *
474	     * @param telephone the raw telephone value, possibly {@code null}
475	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
476	     */
477	    private String toE164(String telephone) {
478	        if (telephone == null) {
479	            return null;
480	        }
481	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
482	        boolean hasPlus = cleaned.startsWith("+");
483	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
484	        String nationalSignificant = hasPlus
485	            ? digits
486	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
487	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
488	            return null;
489	        }
490	        if (!hasValidNationalNumberLength(nationalSignificant)) {
491	            return null;
492	        }
493	        return "+" + nationalSignificant;
494	    }
495	
496	    /**
497	     * Checks the national-number length of an E.164 number (country code plus national significant
498	     * digits, no leading {@code '+'}) against the per-country requirement in
499	     * {@link #NATIONAL_NUMBER_LENGTHS}. The longest listed country code that prefixes the number
500	     * selects the requirement, and the remaining digits must number exactly that many. A number whose
501	     * country code is not listed carries no per-country length requirement and is accepted.
502	     *
503	     * @param nationalSignificant the digits of the E.164 number, country code first, without the
504	     *                            leading {@code '+'}
505	     * @return {@code true} if the national-number length is correct for the country code, or the
506	     *         country code has no listed requirement; {@code false} otherwise
507	     */
508	    private boolean hasValidNationalNumberLength(String nationalSignificant) {
509	        String countryCode = NATIONAL_NUMBER_LENGTHS.keySet().stream()
510	            .filter(nationalSignificant::startsWith)
511	            .max(Comparator.comparingInt(String::length))
512	            .orElse(null);
513	        if (countryCode == null) {
514	            return true;
515	        }
516	        int nationalLength = nationalSignificant.length() - countryCode.length();
517	        return nationalLength == NATIONAL_NUMBER_LENGTHS.get(countryCode);
518	    }
519	
520	    /**
521	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
522	     * is left unset. When a value is present it must be a syntactically valid address whose domain is
523	     * not on the disposable-domain blocklist ({@link #DISPOSABLE_EMAIL_DOMAINS}); the stored and
524	     * returned value is that address lower-cased.
525	     *
526	     * @param email the raw email value submitted by the client, or {@code null} if omitted
527	     * @return the lower-cased email, or {@code null} if none was supplied
528	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
529	     *                                     or its domain is a disposable-mail domain, yielding a 400
530	     *                                     response
531	     */
532	    private String normalizeEmail(String email) {
533	        if (email == null) {
534	            return null;
535	        }
536	        if (!EMAIL_PATTERN.matcher(email).matches()) {
537	            throw new InvalidOwnerFieldsException(List.of("email"));
538	        }
539	        String normalized = email.toLowerCase(Locale.ROOT);
540	        String domain = normalized.substring(normalized.indexOf('@') + 1);
541	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
542	            throw new InvalidOwnerFieldsException(List.of("email"));
543	        }
544	        return normalized;
545	    }
546	
547	    /**
548	     * Counts the existing owners that, before this create, already share the given first name and
549	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
550	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
551	     * been saved yet, so it is never included in the count.
552	     *
553	     * @param firstName the first name of the owner being created
554	     * @param lastName  the last name of the owner being created
555	     * @return the number of existing owners sharing both names
556	     */
557	    private int countNamesakes(String firstName, String lastName) {
558	        String normalizedFirstName = normalizeForComparison(firstName);
559	        String normalizedLastName = normalizeForComparison(lastName);
560	        return (int) this.clinicService.findAllOwners().stream()
561	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
562	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
563	            .count();
564	    }
565	
566	    /**
567	     * Builds the owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is
568	     * the region code derived from the owner's postcode ({@link #regionForPostcode}, {@code 'UNKNOWN'}
569	     * when the postcode is absent or in no known range), and {@code HASH8} is the first eight
570	     * upper-cased hex characters of the SHA-256 digest of the owner's normalized telephone followed by
571	     * the last name (e.g. {@code 'NSW-1A2B3C4D'}). The identity carries no sequence number, so the
572	     * same postcode region, telephone and last name always yield the same customer code.
573	     *
574	     * <p>If the computed code collides with an existing owner's {@code customerCode}, it is
575	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes
576	     * it unique, so distinct owners always receive distinct customer codes.
577	     *
578	     * @param postcode  the owner's validated postcode, or {@code null} if none was supplied
579	     * @param telephone the owner's normalized (E.164) telephone
580	     * @param lastName  the owner's last name
581	     * @return the formatted, de-duplicated customer code
582	     */
583	    private String generateCustomerCode(String postcode, String telephone, String lastName) {
584	        String region = regionForPostcode(postcode);
585	        String hash8 = hashHex(telephone + lastName, 8);
586	        String baseCode = region + "-" + hash8;
587	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
588	            .map(Owner::getCustomerCode)
589	            .filter(Objects::nonNull)
590	            .collect(Collectors.toSet());
591	        if (!existingCodes.contains(baseCode)) {
592	            return baseCode;
593	        }
594	        int n = 2;
595	        while (existingCodes.contains(baseCode + "-" + n)) {
596	            n++;
597	        }
598	        return baseCode + "-" + n;
599	    }
600	
601	    /**
602	     * Resolves the region code for a postcode by its known 4-digit range in {@link #REGION_POSTCODES}
603	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code 'UNKNOWN'}
604	     * when the postcode is {@code null}, not exactly 4 digits, or falls in no known range. This is the
605	     * {@code <REGION>} segment baked into the {@code customerCode}.
606	     *
607	     * @param postcode the owner's postcode, or {@code null}
608	     * @return the region code, or {@code 'UNKNOWN'}
609	     */
610	    private String regionForPostcode(String postcode) {
611	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
612	            return "UNKNOWN";
613	        }
614	        int value = Integer.parseInt(postcode);
615	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
616	            int[] range = entry.getValue();
617	            if (value >= range[0] && value <= range[1]) {
618	                return entry.getKey();
619	            }
620	        }
621	        return "UNKNOWN";
622	    }
623	
624	    /**
625	     * Resolves the region code for a city via the fixed {@link #CITY_REGION} table
626	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), returning {@code 'UNKNOWN'}
627	     * when the city is not listed. Used to validate an owner's optional postcode against its city's
628	     * region.
629	     *
630	     * @param city the owner's city
631	     * @return the region code, or {@code 'UNKNOWN'}
632	     */
633	    private String regionForCity(String city) {
634	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
635	    }
636	
637	    /**
638	     * Returns the first {@code length} upper-cased hex characters of the SHA-256 digest of the given
639	     * input. Used for the {@code <HASH8>} segment of a {@code customerCode} (length 8) and for the
640	     * deterministic {@code householdId} (length 12).
641	     *
642	     * @param input  the value to hash
643	     * @param length the number of leading hex characters to return
644	     * @return the first {@code length} upper-cased hex characters of its SHA-256 digest
645	     */
646	    private String hashHex(String input, int length) {
647	        try {
648	            byte[] digest = MessageDigest.getInstance("SHA-256")
649	                .digest(input.getBytes(StandardCharsets.UTF_8));
650	            StringBuilder hex = new StringBuilder(digest.length * 2);
651	            for (byte b : digest) {
652	                hex.append(String.format("%02x", b));
653	            }
654	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
655	        } catch (NoSuchAlgorithmException e) {
656	            throw new IllegalStateException("SHA-256 algorithm not available", e);
657	        }
658	    }
659	
660	    /**
661	     * Counts the existing owners already in the given city, used to derive the per-city sequence of a
662	     * {@code customerCode}. Cities are compared case-insensitively with surrounding and internal
663	     * whitespace collapsed, consistent with the other owner-field comparisons. The owner being created
664	     * has not been saved yet, so it is never included in the count.
665	     *
666	     * @param city the city of the owner being created
667	     * @return the number of existing owners in that city
668	     */
669	    private int countOwnersInCity(String city) {
670	        String normalizedCity = normalizeForComparison(city);
671	        return (int) this.clinicService.findAllOwners().stream()
672	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
673	            .count();
674	    }
675	
676	    /**
677	     * Rejects creation of an owner whose city already contains the maximum number of owners
678	     * ({@value #CITY_CAPACITY}). Owners are counted per city case-insensitively with surrounding and
679	     * internal whitespace collapsed, consistent with the other owner-field comparisons.
680	     *
681	     * @param city the city of the owner being created
682	     * @throws OwnerCityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more
683	     *                                      owners, yielding a 409 Conflict response
684	     */
685	    private void rejectCityAtCapacity(String city) {
686	        if (countOwnersInCity(city) >= CITY_CAPACITY) {
687	            throw new OwnerCityAtCapacityException(city);
688	        }
689	    }
690	
691	    /**
692	     * Rejects creation of an owner once the given business day has already reached its daily quota
693	     * of {@value #DAILY_OWNER_LIMIT} owners. Owners are counted by their {@code registrationDate}
694	     * being that day — the adjusted business day the owner being created will carry — so the quota
695	     * applies per business day. The owner being created has not been saved yet, so it is never
696	     * included in the count.
697	     *
698	     * @param registrationDate the adjusted business-day registration date of the owner being created
699	     * @throws DailyOwnerLimitReachedException if {@value #DAILY_OWNER_LIMIT} or more owners already
700	     *                                         carry that registration date, yielding a
701	     *                                         429 Too Many Requests response
702	     */
703	    private void rejectDailyLimitReached(LocalDate registrationDate) {
704	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
705	            throw new DailyOwnerLimitReachedException(registrationDate);
706	        }
707	    }
708	
709	    /**
710	     * Counts the existing owners that carry the given day as their {@code registrationDate} — the same
711	     * per-business-day bucket the daily create-limit and the bulk-signup warning both accumulate over.
712	     *
713	     * @param registrationDate the business day to count owners for
714	     * @return the number of existing owners registered on that day
715	     */
716	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
717	        return this.clinicService.findAllOwners().stream()
718	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
719	            .count();
720	    }
721	
722	    /**
723	     * Sets the {@code bulkSignupWarning} flag on an owner response. The flag is {@code true} when more
724	     * than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the current business day's
725	     * {@code registrationDate} — the business day a create would land on right now — and {@code false}
726	     * otherwise.
727	     *
728	     * @param ownerDto the owner response to flag
729	     */
730	    private void applyBulkSignupWarning(OwnerDto ownerDto) {
731	        LocalDate today = toBusinessDay(LocalDate.now());
732	        ownerDto.setBulkSignupWarning(countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
733	    }
734	
735	    /**
736	     * Rolls a registration date forward to a business day. A date that falls on a Saturday, a Sunday
737	     * or a listed {@linkplain #PUBLIC_HOLIDAYS public holiday} is rolled forward one day at a time
738	     * until it reaches the next non-holiday weekday; a date already on a non-holiday weekday is
739	     * returned unchanged. This applies to the effective registration date whether it was supplied in
740	     * the request or defaulted to the server date, and the adjusted value is what gets stored as
741	     * {@code registrationDate} and feeds every value derived from it (such as the membership number's
742	     * year segment and the daily create-limit's per-day bucket).
743	     *
744	     * @param date the effective registration date, supplied or defaulted
745	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
746	     */
747	    private LocalDate toBusinessDay(LocalDate date) {
748	        LocalDate adjusted = date;
749	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
750	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY
751	            || PUBLIC_HOLIDAYS.contains(adjusted)) {
752	            adjusted = adjusted.plusDays(1);
753	        }
754	        return adjusted;
755	    }
756	
757	    /**
758	     * Rejects creation of an owner whose derived {@code identityKey} exactly matches an existing
759	     * owner's. The identity key — {@code '<normalizedTelephone>|<email or empty>|<householdId or
760	     * empty>'} — is the single value that consolidates all duplicate detection: the previously
761	     * separate telephone, email and household checks are all expressed through it. Because the
762	     * telephone is part of the key, two members of the same household (same {@code householdId})
763	     * with different telephones have different identity keys and are both allowed; only a whole-key
764	     * match is a duplicate. The owner being created already carries its normalized telephone,
765	     * email and (if any) household id, and existing owners store the same normalized forms, so the
766	     * keys are compared directly.
767	     *
768	     * @param owner the owner being created, with its telephone, email and household id already set
769	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key,
770	     *                                         yielding a 409 Conflict response
771	     */
772	    private void rejectDuplicateIdentity(Owner owner) {
773	        String identityKey = owner.getIdentityKey();
774	        boolean inUse = this.clinicService.findAllOwners().stream()
775	            .filter(this::isNotDeleted)
776	            .map(Owner::getIdentityKey)
777	            .anyMatch(identityKey::equals);
778	        if (inUse) {
779	            throw new DuplicateOwnerIdentityException(identityKey);
780	        }
781	    }
782	
783	    /**
784	     * Flags the owner being created as a possible (soft) duplicate. A possible duplicate is an owner
785	     * that is not a hard duplicate (its identity key is unique, so it has already passed
786	     * {@link #rejectDuplicateIdentity}) yet belongs to the same household as an existing owner — that
787	     * is, it carries the same computed {@code householdId} (derived from the last name and postcode) —
788	     * while carrying a different telephone. When such a match exists the owner is created with
789	     * {@code possibleDuplicate} set to {@code true} and {@code possibleDuplicateOf} set to the matching
790	     * owner's id (the earliest matching owner by id); otherwise {@code possibleDuplicate} is
791	     * {@code false} and {@code possibleDuplicateOf} is left unset.
792	     *
793	     * <p>An owner that declares household membership via {@code sharesHousehold} is never flagged: a
794	     * declared household member is not a suspected duplicate. (Without that declaration a same-household
795	     * owner is rejected outright by {@link #rejectHouseholdDuplicate}, so no suspected-duplicate match
796	     * survives for a created owner either.)
797	     *
798	     * @param owner           the owner being created, with its household id and telephone already set
799	     * @param sharesHousehold whether the owner declared itself a member of an existing household
800	     */
801	    private void applyPossibleDuplicate(Owner owner, boolean sharesHousehold) {
802	        owner.setPossibleDuplicate(false);
803	        if (sharesHousehold) {
804	            return;
805	        }
806	        String householdId = owner.getHouseholdId();
807	        if (householdId == null || householdId.isBlank()) {
808	            return;
809	        }
810	        String telephone = owner.getTelephone();
811	        Owner match = this.clinicService.findAllOwners().stream()
812	            .filter(this::isNotDeleted)
813	            .filter(existing -> householdId.equals(existing.getHouseholdId())
814	                && !Objects.equals(telephone, existing.getTelephone()))
815	            .min(Comparator.comparingInt(Owner::getId))
816	            .orElse(null);
817	        if (match != null) {
818	            owner.setPossibleDuplicate(true);
819	            owner.setPossibleDuplicateOf(match.getId());
820	        }
821	    }
822	
823	    /**
824	     * Computes the owner's deterministic {@code householdId}: the first twelve upper-cased hex
825	     * characters of the SHA-256 digest of the normalized last name and the postcode joined by a
826	     * {@code '|'}. Because the value derives only from the last name and postcode, every owner that
827	     * shares both automatically shares the same household id, so the household is keyed on
828	     * {@code (lastName, postcode)} with no opt-in required. The last name is normalized for comparison
829	     * (trimmed, internal whitespace collapsed, lower-cased) so values differing only in case or spacing
830	     * still land in the same household.
831	     *
832	     * @param lastName the owner's last name
833	     * @param postcode the owner's validated postcode, or {@code null} if none was supplied
834	     * @return the derived household id, or {@code null} when the owner has no postcode and so belongs
835	     *         to no postcode-keyed household
836	     */
837	    private String computeHouseholdId(String lastName, String postcode) {
838	        if (postcode == null) {
839	            return null;
840	        }
841	        return hashHex(normalizeForComparison(lastName) + "|" + postcode, 12);
842	    }
843	
844	    /**
845	     * Rejects creation of an owner that would join an existing household it has not declared membership
846	     * of. The household is keyed on the computed {@code householdId} (derived from the last name and
847	     * postcode), so any existing owner carrying the same {@code householdId} is a member of the same
848	     * household. A second owner in that household is a household duplicate and is rejected with a
849	     * {@code 409 Conflict} unless the request opts in via {@code sharesHousehold}, in which case this
850	     * check is bypassed and the owner is created as a declared household member. An owner with no
851	     * {@code householdId} (no postcode) belongs to no household and is never rejected here.
852	     *
853	     * @param owner the owner being created, with its household id already computed
854	     * @throws DuplicateHouseholdException if an existing owner already belongs to the same
855	     *                                     household, yielding a 409 Conflict response
856	     */
857	    private void rejectHouseholdDuplicate(Owner owner) {
858	        String householdId = owner.getHouseholdId();
859	        if (householdId == null || householdId.isBlank()) {
860	            return;
861	        }
862	        boolean inUse = this.clinicService.findAllOwners().stream()
863	            .filter(this::isNotDeleted)
864	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
865	        if (inUse) {
866	            throw new DuplicateHouseholdException(householdId);
867	        }
868	    }
869	
870	    /**
871	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
872	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
873	     * the result is lower-cased.
874	     *
875	     * @param value the value to normalize, possibly {@code null}
876	     * @return the normalized value, or an empty string if {@code value} is {@code null}
877	     */
878	    private String normalizeForComparison(String value) {
879	        if (value == null) {
880	            return "";
881	        }
882	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
883	    }
884	
885	    /**
886	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
887	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
888	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
889	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
890	     * This normalized value is what gets stored and returned.
891	     *
892	     * @param address the raw address value submitted by the client, possibly {@code null}
893	     * @return the normalized address, or an empty string if {@code address} is {@code null}
894	     */
895	    private String normalizeAddress(String address) {
896	        if (address == null) {
897	            return "";
898	        }
899	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
900	        if (collapsed.isEmpty()) {
901	            return collapsed;
902	        }
903	        String[] tokens = collapsed.split(" ");
904	        StringBuilder normalized = new StringBuilder(collapsed.length());
905	        for (int i = 0; i < tokens.length; i++) {
906	            if (i > 0) {
907	                normalized.append(' ');
908	            }
909	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
910	        }
911	        return normalized.toString();
912	    }
913	
914	    /**
915	     * Reports whether the submitted owner supplies an address in either accepted form: a non-blank
916	     * structured {@code addressLine1}, or a non-blank flat {@code address}. The structured form is
917	     * preferred when present, but either satisfies the address requirement, keeping the create
918	     * contract backward-compatible with earlier flat-address-only owners.
919	     *
920	     * @param ownerFieldsDto the submitted owner fields
921	     * @return {@code true} if an address is supplied in either form
922	     */
923	    private boolean hasAddress(OwnerFieldsDto ownerFieldsDto) {
924	        return !isBlank(ownerFieldsDto.getAddressLine1())
925	            || !isBlank(normalizeAddress(ownerFieldsDto.getAddress()));
926	    }
927	
928	    /**
929	     * Applies the owner's address, preferring the structured form over the flat one. When a non-blank
930	     * {@code addressLine1} is supplied, it and the optional {@code addressLine2} are normalized
931	     * ({@link #normalizeAddress}) and stored, and the owner's composed {@code address} is set to the
932	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
933	     * appended when {@code addressLine2} is present. Otherwise the flat {@code address} is normalized
934	     * and stored and the structured lines are left unset. This keeps earlier flat-address owners
935	     * working while letting everything that reads the address use the composed, normalized value.
936	     *
937	     * @param owner          the owner being created
938	     * @param ownerFieldsDto the submitted owner fields
939	     */
940	    private void applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
941	        if (!isBlank(ownerFieldsDto.getAddressLine1())) {
942	            String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
943	            String line2 = isBlank(ownerFieldsDto.getAddressLine2())
944	                ? null
945	                : normalizeAddress(ownerFieldsDto.getAddressLine2());
946	            owner.setAddressLine1(line1);
947	            owner.setAddressLine2(line2);
948	            owner.setAddress(line2 != null ? line1 + " " + line2 : line1);
949	        } else {
950	            owner.setAddressLine1(null);
951	            owner.setAddressLine2(null);
952	            owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
953	        }
954	    }
955	}
