245	    public void setDeleted(Boolean deleted) {
246	        this.deleted = deleted;
247	    }
248	
249	    /**
250	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
251	     */
252	    @Transient
253	    public String getDisplayName() {
254	        return this.getLastName() + ", " + this.getFirstName();
255	    }
256	
257	    /**
258	     * The owner's salutation: the honorific {@link #getTitle() title} and the last name separated by
259	     * a single space (e.g. {@code 'DR who'}), or just the last name when the owner has no title.
260	     * Derived from the owner's own fields.
261	     */
262	    @Transient
263	    public String getSalutation() {
264	        if (this.title == null || this.title.isBlank()) {
265	            return this.getLastName();
266	        }
267	        return this.title + " " + this.getLastName();
268	    }
269	
270	    /**
271	     * The owner's initials: the upper-cased first letters of the first and last name,
272	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
273	     */
274	    @Transient
275	    public String getInitials() {
276	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
277	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
278	    }
279	
280	    /**
281	     * The fiscal year a date falls in. The fiscal year starts on 1 July and is identified by the
282	     * calendar year in which it ends: a date in July through December belongs to the fiscal year
283	     * ending the following calendar year, a date in January through June to the fiscal year ending
284	     * that same calendar year.
285	     */
286	    private static int fiscalYearOf(LocalDate date) {
287	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
288	    }
289	
290	    /**
291	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY} is the last two digits of
292	     * the fiscal year (which starts on 1 July) that the business-day-adjusted {@code registrationDate}
293	     * falls in (e.g. {@code 'FY26'} for a registration date between 1 July 2025 and 30 June 2026).
294	     * Derived from the owner's own {@code registrationDate}; {@code null} until it is set.
295	     */
296	    @Transient
297	    public String getFiscalYear() {
298	        if (this.registrationDate == null) {
299	            return null;
300	        }
301	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
302	    }
303	
304	    /**
305	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
306	     * the last two digits of the fiscal year carried by the business-day-adjusted registration date
307	     * (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived from the owner's own fields; {@code null} until both
308	     * the customer code and registration date are set.
309	     */
310	    @Transient
311	    public String getMembershipNumber() {
312	        if (this.customerCode == null || this.registrationDate == null) {
313	            return null;
314	        }
315	        return String.format("%s-M%02d", this.customerCode, fiscalYearOf(this.registrationDate) % 100);
316	    }
317	
318	    /**
319	     * A single Luhn check digit (0-9) computed over the digits contained in the owner's
320	     * {@code customerCode}. Derived from the owner's own fields; {@code null} until the customer
321	     * code is set. The standard Luhn algorithm is applied to the digits of the customer code, from
322	     * right to left, doubling every second digit (subtracting 9 when the doubled value exceeds 9).
323	     */
324	    @Transient
325	    public Integer getCheckDigit() {
326	        if (this.customerCode == null) {
327	            return null;
328	        }
329	        int sum = 0;
330	        boolean dbl = true;
331	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
332	            char c = this.customerCode.charAt(i);
333	            if (c < '0' || c > '9') {
334	                continue;
335	            }
336	            int d = c - '0';
337	            if (dbl) {
338	                d *= 2;
339	                if (d > 9) {
340	                    d -= 9;
341	                }
342	            }
343	            sum += d;
344	            dbl = !dbl;
345	        }
346	        return (10 - (sum % 10)) % 10;
347	    }
348	
349	    /**
350	     * The owner's membership points, a score accumulated from the owner's own fields. It starts at
351	     * 0 and gains: 2 when the owner has an email address; 1 when the owner is unique
352	     * ({@code namesakeCount} is 0); 2 when the owner belongs to a household of 3 or more members
353	     * (the owner together with their pets); and 3 when the owner's tenure spans at least one elapsed
354	     * fiscal year, measured as the difference between the fiscal year of today and the fiscal year of
355	     * {@code registrationDate}. Because a newly created owner has zero elapsed fiscal years of tenure,
356	     * a new owner never earns the tenure points. The score feeds {@link #getMembershipLevel()}.
357	     */
358	    @Transient
359	    public Integer getMembershipPoints() {
360	        int points = 0;
361	        boolean hasEmail = this.email != null && !this.email.isBlank();
362	        if (hasEmail) {
363	            points += 2;
364	        }
365	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
366	        if (unique) {
367	            points += 1;
368	        }
369	        int householdSize = 1 + getPetsInternal().size();
370	        if (householdSize >= 3) {
371	            points += 2;
372	        }
373	        boolean tenured = this.registrationDate != null
374	            && fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) > 0;
375	        if (tenured) {
376	            points += 3;
377	        }
378	        return points;
379	    }
380	
381	    /**
382	     * The owner's numeric membership level, from 1 to 4, derived from {@link #getMembershipPoints()}:
383	     * level 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
384	     */
385	    @Transient
386	    public Integer getMembershipLevel() {
387	        int points = getMembershipPoints();
388	        if (points >= 6) {
389	            return 4;
390	        }
391	        if (points >= 4) {
392	            return 3;
393	        }
394	        if (points >= 2) {
395	            return 2;
396	        }
397	        return 1;
398	    }
399	
400	    /**
401	     * The owner's locality: the canonical region carried by the {@code customerCode}, which is the
402	     * {@code <REGION>} segment preceding its first {@code '-'} (e.g. {@code 'NSW'} for customer code
403	     * {@code 'NSW-1A2B3C4D'}). The region is the one derived from the postcode at creation time and
404	     * baked into the identity. {@code 'UNKNOWN'} when the owner has no customer code yet.
405	     */
406	    @Transient
407	    public String getLocality() {
408	        if (this.customerCode == null) {
409	            return "UNKNOWN";
410	        }
411	        int dash = this.customerCode.indexOf('-');
412	        return dash < 0 ? "UNKNOWN" : this.customerCode.substring(0, dash);
413	    }
414	
415	    /**
416	     * Fixed region-to-timezone lookup mapping each canonical region to its IANA timezone name:
417	     * {@code NSW -> 'Australia/Sydney'}, {@code VIC -> 'Australia/Melbourne'},
418	     * {@code QLD -> 'Australia/Brisbane'}.
419	     */
420	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
421	        "NSW", "Australia/Sydney",
422	        "VIC", "Australia/Melbourne",
423	        "QLD", "Australia/Brisbane");
424	
425	    /**
426	     * The owner's timezone: the IANA name derived from the owner's {@link #getLocality() locality}
427	     * via the fixed region-to-timezone table ({@code NSW -> 'Australia/Sydney'},
428	     * {@code VIC -> 'Australia/Melbourne'}, {@code QLD -> 'Australia/Brisbane'}). {@code null} when
429	     * the locality is not one of these regions.
430	     */
431	    @Transient
432	    public String getTimezone() {
433	        return REGION_TIMEZONE.get(getLocality());
434	    }
435	
436	    /**
437	     * The owner's identity key: a single derived value that consolidates all duplicate detection,
438	     * formatted {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. The
439	     * telephone is the stored E.164 value, the email its stored lower-cased form (empty when the
440	     * owner has none), and the household id the stored shared identifier (empty when the owner is
441	     * not part of a shared household). Two owners are duplicates only when their whole identity keys
442	     * are equal; because the telephone is part of the key, two members of the same household with
443	     * different telephones have different identity keys.
444	     */
445	    @Transient
446	    public String getIdentityKey() {
447	        String telephonePart = this.telephone == null ? "" : this.telephone;
448	        String emailPart = this.email == null ? "" : this.email;
449	        String householdPart = this.householdId == null ? "" : this.householdId;
450	        return telephonePart + "|" + emailPart + "|" + householdPart;
451	    }
452	
453	    /**
454	     * The owner's preferred contact channel, derived from the owner's own fields:
455	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
456	     */
457	    @Transient
458	    public String getContactPreference() {
459	        boolean hasEmail = this.email != null && !this.email.isBlank();
460	        return hasEmail ? "EMAIL" : "PHONE";
461	    }
462	
463	    /**
464	     * The owner's age band, derived from the owner's own fields: the whole number of years from
465	     * {@code birthDate} to {@code registrationDate} placed into a band — {@code 'MINOR'} when under
466	     * 18, {@code 'ADULT'} when 18 to 64, and {@code 'SENIOR'} when 65 or older. The age is measured
467	     * as of the registration date rather than today, so the band is stable over time. {@code null}
468	     * when the owner has no birth date (or no registration date to measure against).
469	     */
470	    @Transient
471	    public String getAgeBand() {
472	        if (this.birthDate == null || this.registrationDate == null) {
473	            return null;
474	        }
475	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
476	        if (age < 18) {
477	            return "MINOR";
478	        }
479	        if (age < 65) {
480	            return "ADULT";
481	        }
482	        return "SENIOR";
483	    }
484	
485	    protected Set<Pet> getPetsInternal() {
486	        if (this.pets == null) {
487	            this.pets = new HashSet<>();
488	        }
489	        return this.pets;
490	    }
491	
492	    protected void setPetsInternal(Set<Pet> pets) {
493	        this.pets = pets;
494	    }
495	
496	    public List<Pet> getPets() {
497	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
498	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
499	        return Collections.unmodifiableList(sortedPets);
500	    }
501	
502	    public void setPets(List<Pet> pets) {
503	        this.pets = new HashSet<>(pets);
504	    }
505	
506	    public void addPet(Pet pet) {
507	        getPetsInternal().add(pet);
508	        pet.setOwner(this);
509	    }
510	
511	    /**
512	     * Return the Pet with the given name, or null if none found for this Owner.
513	     *
514	     * @param name to test
515	     * @return true if pet name is already in use
516	     */
517	    public Pet getPet(String name) {
518	        return getPet(name, false);
519	    }
520	
521	    /**
522	     * Return the Pet with the given name, or null if none found for this Owner.
523	     *
524	     * @param name to test
525	     * @return true if pet name is already in use
526	     */
527	    public Pet getPet(String name, boolean ignoreNew) {
528	        name = name.toLowerCase();
529	        for (Pet pet : getPetsInternal()) {
530	            if (!ignoreNew || !pet.isNew()) {
531	                String compName = pet.getName();
532	                compName = compName.toLowerCase();
533	                if (compName.equals(name)) {
534	                    return pet;
535	                }
536	            }
537	        }
538	        return null;
539	    }
540	
541	    public Pet getPet(Integer petId) {
542	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
543	    }
544	
545	    @Override
546	    public String toString() {
547	        return new ToStringCreator(this)
548	
549	            .append("id", this.getId())
550	            .append("new", this.isNew())
551	            .append("lastName", this.getLastName())
552	            .append("firstName", this.getFirstName())
553	            .append("address", this.address)
554	            .append("city", this.city)
555	            .append("telephone", this.telephone)
556	            .toString();
557	    }
558	}
